/* access_app/static/app.js — panel local; no librerías, telemetría ni imágenes externas. */
'use strict';
const $ = id => document.getElementById(id);
let token = sessionStorage.getItem('access-token') || '';
let currentUser=null, setupRequired=false, entryAllowed=true;
let lastInteraction=Date.now();
let stream = null, running = false, enrolling = false, cameraId = 'browser-access';
let passToken = null, passExpiry = 0, photos = [], residents = [], events = [], cameras = [];
let loopVersion = 0, toastTimer, lastResidentId = null;
const fmt = value => new Intl.DateTimeFormat('es-AR', {timeZone:'America/Argentina/Buenos_Aires',dateStyle:'short',timeStyle:'medium'}).format(new Date(value));
function node(tag, text, cls) { const n = document.createElement(tag); if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n; }
function toast(message) { $('toast').textContent=message;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>{$('toast').hidden=true;},6500); }
async function api(path, options={}) {
 const sessionAtSend=token;
 const res = await fetch(path,{...options,headers:{'Authorization':'Bearer '+token,'Content-Type':'application/json',...options.headers}});
 let data;try{data=await res.json();}catch{throw new Error('El servidor no devolvió una respuesta válida');}
 if(sessionAtSend!==token&&!['/api/auth/setup','/api/auth/login','/api/auth/status'].includes(path.split('?')[0]))throw new Error('La sesión cambió; se descartó la respuesta anterior.');
 if(!res.ok){if(res.status===401){clearSession();if(!$('login-dialog').open)$('login-dialog').showModal();}
 const msg=Array.isArray(data.detail)?data.detail.map(v=>v.msg).join('. '):data.detail;throw new Error(msg||'No se pudo completar la operación');}if(res.headers.get('X-Audit-Status')==='failed')toast('La operación se guardó, pero falló su auditoría. Se bloquearon nuevos cambios hasta revisarla.');return data;
}
const post=(path,data={})=>api(path,{method:'POST',body:JSON.stringify(data)});
const titles={access:['Un acceso más claro.','Verificá residentes y registrá pasos observados desde un mismo lugar.'],residents:['Cada residente, registrado.','Altas voluntarias y control del padrón del piloto.'],visits:['Recibí visitas con autorización.','Permisos temporales, mantenimiento y pasos confirmados por seguridad.'],events:['Un historial verificable.','Pasos observados, con fecha, hora y evidencia de registro.'],cameras:['Tus puntos de observación.','Conectá fuentes privadas compatibles, con una finalidad definida.'],evaluation:['Medí, compará y documentá.','Ensayos voluntarios para construir evidencia del Proyecto Integrador.'],restrictions:['Restricciones con revisión.','Decisiones administrativas con motivo, vigencia y verificación de identidad.'],users:['Cada operador, con su cuenta.','Permisos separados para administración y seguridad.'],audit:['Acciones con responsable.','Historial local de cambios, accesos de cuenta y verificaciones de integridad.'],about:['Primero, una prueba responsable.','Alcance, privacidad y límites de esta versión.']};
function setView(name){if(currentUser?.role!=='admin'&&['users','audit','evaluation'].includes(name))name='access';if(name==='users')loadUsers().catch(e=>toast(e.message));if(name==='restrictions')loadRestrictions().catch(e=>toast(e.message));if(name==='audit')loadAudit().catch(e=>toast(e.message));for(const el of document.querySelectorAll('.view'))el.hidden=el.id!=='view-'+name;for(const el of document.querySelectorAll('.nav-item'))el.classList.toggle('active',el.dataset.view===name);$('page-title').textContent=titles[name][0];$('page-subtitle').textContent=titles[name][1];}
for(const b of document.querySelectorAll('[data-view]'))b.addEventListener('click',()=>setView(b.dataset.view));
function applyRole(){const admin=currentUser?.role==='admin';for(const el of document.querySelectorAll('[data-admin-only]'))el.hidden=!admin;$('operator-summary').textContent=currentUser?currentUser.name+' · '+(admin?'Administración':'Seguridad'):'Sin sesión';}
async function refresh(){
 currentUser=await api('/api/auth/me');applyRole();
 if(currentUser.force_change){$('login-dialog').close();$('password-error').textContent='Tu cuenta necesita una contraseña propia antes de operar.';if(!$('password-dialog').open)$('password-dialog').showModal();return;}
 const [s,r,e,c]=await Promise.all([api('/api/status'),api('/api/residents'),api('/api/events'),api('/api/cameras')]);
 residents=r;events=e;cameras=c;$('resident-count').textContent=s.residents;$('event-count').textContent=s.events;$('model-status').textContent=s.models_ready&&s.pad_ready?'Preparado':'No disponible';$('model-detail').textContent=s.model_error||s.pad_error||'PAD RGB activo · umbrales por validar';$('retention').textContent=s.retention_days+' días';
 renderResidents();renderEvents();renderCameras();renderTrialParticipants();renderVisitSelectors();renderRestrictionResident();$('visits-authorized').textContent=s.visits.authorized_now;$('visits-inside').textContent=s.visits.inside;
 await Promise.all([currentUser.role==='admin'?Promise.all([refreshEvaluation(),refreshPadEvaluation()]):Promise.resolve(),loadVisits(),loadRestrictions()]);
 if(s.audit_error)toast('La auditoría requiere revisión: los cambios están bloqueados.');
}

function renderResidents(){const body=$('residents-body');body.replaceChildren();const q=$('resident-search').value.toLocaleLowerCase();let count=0;for(const r of residents){if(![r.name,r.unit,r.building].join(' ').toLocaleLowerCase().includes(q))continue;count++;const tr=node('tr');for(const v of [r.name,r.unit,r.building,fmt(r.consent_at)])tr.append(node('td',v));const td=node('td');const b=node('button','Dar de baja','danger-button');b.addEventListener('click',async()=>{if(!confirm('¿Dar de baja a '+r.name+'? Se eliminarán su plantilla, sus datos, sus pasos y las autorizaciones de visitas asociadas. Si hay visitas sin salida registrada, la baja se bloqueará hasta revisarlas.'))return;try{await api('/api/residents/'+r.id,{method:'DELETE'});clearIdentity();await refresh();toast('Baja y eliminación completadas.');}catch(e){toast(e.message);}});if(currentUser?.role==='admin')td.append(b);else td.textContent='Consulta';tr.append(td);body.append(tr);}$('residents-empty').hidden=count>0;$('residents-empty').textContent=q?'No hay residentes que coincidan con la búsqueda.':'El padrón está vacío. Registrá al primer participante.';}
$('resident-search').addEventListener('input',renderResidents);
function renderEvents(){const body=$('events-body');body.replaceChildren();for(const e of events){const tr=node('tr');for(const v of [fmt(e.occurred_at),e.resident?.name||'Sin identificación',e.resident?.unit||'—'])tr.append(node('td',v));const dir=node('td');dir.append(node('span',e.direction==='entrada'?'Entrada':'Salida','direction'));tr.append(dir,node('td',e.camera_label||e.camera_id),node('td','Confirmación manual · puerta simulada'));body.append(tr);}$('events-empty').hidden=events.length>0;$('more-events').hidden=events.length===0||events.length%100!==0;const recent=$('recent-events');recent.replaceChildren();recent.className=events.length?'':'empty-list';if(!events.length){recent.textContent='Todavía no hay movimientos registrados.';return;}for(const e of events.slice(0,4)){const row=node('div',undefined,'recent-row'),icon=node('span',e.direction==='entrada'?'↗':'↙','event-icon'),detail=node('div');detail.append(node('strong',e.resident?.name||'Sin identificación'),node('small',(e.resident?.building||'')+' · Unidad '+(e.resident?.unit||'—')+' · '+e.direction));row.append(icon,detail,node('time',fmt(e.occurred_at)));recent.append(row);}}
$('refresh-events').addEventListener('click',()=>refresh().catch(e=>toast(e.message)));
$('more-events').addEventListener('click',async()=>{try{const extra=await api('/api/events?before='+events.at(-1).id);events.push(...extra);renderEvents();if(!extra.length)$('more-events').hidden=true;}catch(e){toast(e.message);}});
function renderCameras(){const list=$('cameras-list');list.replaceChildren();const select=$('camera-select');select.replaceChildren(new Option('Cámara de esta computadora','browser-access'));if(!cameras.length)list.append(node('div','Todavía no hay fuentes guardadas. Podés empezar con la cámara de esta computadora.','empty-list'));for(const c of cameras){select.add(new Option(c.label,c.id));const row=node('div',undefined,'camera-item'),detail=node('div',undefined,'camera-item-detail');detail.append(node('strong',c.label),node('small',(c.role==='access'?'Acceso autorizado · identificación':'Observación · sin identidad')+' · '+c.status));const use=node('button','Usar','secondary');use.addEventListener('click',()=>{stopCamera();select.value=c.id;cameraId=c.id;setView('access');startCamera().catch(e=>toast(e.message));});const del=node('button','Quitar','danger-button');del.addEventListener('click',async()=>{if(!confirm('¿Quitar esta cámara del piloto?'))return;try{if(cameraId===c.id)stopCamera();await api('/api/cameras/'+c.id,{method:'DELETE'});if(cameraId===c.id)cameraId='browser-access';await refresh();}catch(e){toast(e.message);}});row.append(detail,use);if(currentUser?.role==='admin')row.append(del);list.append(row);}select.value=cameras.some(c=>c.id===cameraId)?cameraId:'browser-access';renderObservations();}
$('camera-form').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target);try{await post('/api/cameras',{label:f.get('label'),role:f.get('role'),source:f.get('source'),authorized_private_use:f.get('authorized')==='on'});e.target.reset();await refresh();toast('Fuente guardada. La compatibilidad se comprueba al conectarla.');}catch(err){toast(err.message);}});
async function ensureWebcam(){if(stream)return stream;if(!navigator.mediaDevices?.getUserMedia)throw new Error('La cámara requiere una aplicación/navegador compatible.');const selected=$('local-device-select').value;const sessionAtCapture=token;const candidate=await navigator.mediaDevices.getUserMedia({video:{width:{ideal:1280},height:{ideal:720},...(selected?{deviceId:{exact:selected}}:{})},audio:false});if(token!==sessionAtCapture){candidate.getTracks().forEach(t=>t.stop());throw new Error('La sesión cambió.');}stream=candidate;const devices=await navigator.mediaDevices.enumerateDevices();const select=$('local-device-select'),chosen=stream.getVideoTracks()[0]?.getSettings().deviceId;select.replaceChildren(new Option('Predeterminada',''));for(const d of devices.filter(d=>d.kind==='videoinput'))select.add(new Option(d.label||'Cámara '+(select.options.length),d.deviceId));select.value=[...select.options].some(o=>o.value===chosen)?chosen:'';return stream;}
$('local-device-select').addEventListener('change',async()=>{const chosen=$('local-device-select').value;await stopCamera();$('local-device-select').value=chosen;toast('Cámara seleccionada. Pulsá Iniciar cámara para usarla.');});

function clearIdentity(){renderPad();entryAllowed=false;lastResidentId=null;passToken=null;passExpiry=0;$('identity-name').textContent='Esperando una captura';$('identity-unit').textContent='Presentá un solo rostro en el acceso.';$('identity-result').textContent='Sin evaluación';$('identity-result').classList.remove('matched','restricted');$('identity-avatar').classList.remove('matched');$('identity-score').textContent='Una similitud facial no es una probabilidad de identidad.';$('crossing-observed').checked=false;passButtons();}
function passButtons(){const enabled=!!passToken&&Date.now()<passExpiry&&$('crossing-observed').checked;$('confirm-entry').disabled=!enabled||!entryAllowed;$('confirm-exit').disabled=!enabled;}
$('crossing-observed').addEventListener('change',passButtons);setInterval(passButtons,500);
function draw(result){const canvas=$('overlay');canvas.width=result.width;canvas.height=result.height;const ctx=canvas.getContext('2d');ctx.lineWidth=3;ctx.strokeStyle=result.recognized?'#68ddb0':'#d0e1dc';for(const b of result.boxes)ctx.strokeRect(b.x,b.y,b.w,b.h);}
function present(result){draw(result);$('face-count').textContent='Rostros: '+(result.face_count??result.boxes.length);if(result.recognized){entryAllowed=result.entry_allowed!==false&&result.pad?.passed===true;if(lastResidentId!==result.resident.id)$('crossing-observed').checked=false;lastResidentId=result.resident.id;passToken=result.pass_token;passExpiry=Date.now()+result.token_ttl_seconds*1000;$('identity-name').textContent=result.resident.name;$('identity-unit').textContent=result.resident.building+' · Unidad '+result.resident.unit;$('identity-result').textContent=entryAllowed?'Rostro y PAD superados · piloto':'Entrada restringida · revisar';$('identity-result').classList.add('matched');$('identity-avatar').classList.add('matched');$('identity-score').textContent='Similitud coseno: '+result.similarity+' · No es un porcentaje de certeza.';$('identity-result').classList.toggle('restricted',!entryAllowed);}else{clearIdentity();$('identity-name').textContent=result.mode==='detect'?'Detección sin identidad':'Sin identificación suficiente';$('identity-unit').textContent=result.message;$('identity-result').textContent=result.mode==='detect'?result.boxes.length+' rostro(s) detectado(s)':'Revisar captura';}renderPad(result.pad);passButtons();$('scan-status').textContent=result.mode==='detect'?'Detección · sin nombres ni registro de pasos':result.message;}
function capture(video){if(!video.videoWidth)throw new Error('La cámara todavía no tiene imagen. Esperá unos segundos.');const c=document.createElement('canvas');const scale=Math.min(1,1280/video.videoWidth);c.width=Math.round(video.videoWidth*scale);c.height=Math.round(video.videoHeight*scale);c.getContext('2d').drawImage(video,0,0,c.width,c.height);return c.toDataURL('image/jpeg',.9);}
async function startCamera(){await stopCamera();cameraId=$('camera-select').value;const epoch=++loopVersion;try{if(cameraId==='browser-access'){$('video').srcObject=await ensureWebcam();await $('video').play();$('video').hidden=false;$('remote-frame').hidden=true;}else{await post('/api/cameras/'+cameraId+'/connect');$('video').hidden=true;$('remote-frame').hidden=false;}running=true;$('camera-empty').hidden=true;$('start-camera').disabled=true;$('stop-camera').disabled=false;$('camera-live').textContent='Captura periódica';$('camera-live').classList.add('live');loop(epoch);}catch(e){stopCamera();throw e;}}
async function loop(epoch){while(running&&epoch===loopVersion){if(!enrolling){try{const result=cameraId==='browser-access'?await post('/api/analyze?mode='+($('detect-only').checked?'detect':'recognize'),{image:capture($('video')),camera_id:cameraId}):await post('/api/cameras/'+cameraId+'/analyze?mode='+($('detect-only').checked?'detect':'recognize'));if(epoch!==loopVersion)return;if(result.image)$('remote-frame').src=result.image;present(result);}catch(e){if(epoch!==loopVersion)return;clearIdentity();$('scan-status').textContent=e.message;}}await new Promise(resolve=>setTimeout(resolve,1500));}}
function stopCamera(disconnect=true,preserveClip=true){stopClip(preserveClip);const wasRunning=running;running=false;loopVersion++;if(stream&&!enrolling){stream.getTracks().forEach(t=>t.stop());stream=null;}$('video').srcObject=null;$('video').hidden=true;$('remote-frame').hidden=true;$('camera-empty').hidden=false;$('camera-live').textContent='Sin conexión';$('camera-live').classList.remove('live');$('start-camera').disabled=false;$('stop-camera').disabled=true;$('scan-status').textContent='Esperando cámara';$('face-count').textContent='Rostros: —';$('overlay').getContext('2d').clearRect(0,0,$('overlay').width,$('overlay').height);clearIdentity();if(disconnect&&token){const jobs=[post('/api/access/reset',{camera_id:cameraId})];if(wasRunning&&cameraId!=='browser-access')jobs.push(post('/api/cameras/'+cameraId+'/disconnect'));return Promise.allSettled(jobs);}}
$('start-camera').addEventListener('click',()=>startCamera().catch(e=>toast(e.message)));$('stop-camera').addEventListener('click',stopCamera);$('camera-select').addEventListener('change',()=>{stopCamera();cameraId=$('camera-select').value;});$('detect-only').addEventListener('change',clearIdentity);
async function passage(direction){if(!passToken||!$('crossing-observed').checked)return;const current=passToken;passToken=null;passButtons();try{await post('/api/passages',{token:current,camera_id:cameraId,direction,crossing_observed:true});$('crossing-observed').checked=false;await refresh();toast((direction==='entrada'?'Entrada':'Salida')+' confirmada. Puerta física sin accionar.');}catch(e){toast(e.message);}}
$('confirm-entry').addEventListener('click',()=>passage('entrada'));$('confirm-exit').addEventListener('click',()=>passage('salida'));
async function openEnrollment(){if(!token){$('login-dialog').showModal();return;}enrolling=true;photos=[];renderPhotos();$('enroll-error').textContent='';$('enroll-form').reset();$('enroll-dialog').showModal();try{$('enroll-video').srcObject=await ensureWebcam();await $('enroll-video').play();if(!$('enroll-dialog').open&&!running){if(stream)stream.getTracks().forEach(t=>t.stop());stream=null;}}catch(e){$('enroll-error').textContent=e.message;}}
function closeEnrollment(){photos=[];$('photo-previews').replaceChildren();$('enroll-video').srcObject=null;enrolling=false;$('enroll-dialog').close();if(!running&&stream){stream.getTracks().forEach(t=>t.stop());stream=null;}}
$('open-enroll').addEventListener('click',openEnrollment);$('close-enroll').addEventListener('click',closeEnrollment);$('enroll-dialog').addEventListener('cancel',e=>{e.preventDefault();closeEnrollment();});
function renderPhotos(){$('photo-previews').replaceChildren(...photos.map((p,i)=>{const img=node('img');img.src=p;img.alt='Captura temporal '+(i+1);return img;}));$('take-photo').textContent='Tomar captura · '+photos.length+'/3';$('take-photo').disabled=photos.length>=3;$('save-resident').disabled=photos.length<3;$('capture-tip').textContent=['Primera captura: mirá de frente a la cámara.','Segunda captura: girá ligeramente hacia un lado.','Tercera captura: girá ligeramente hacia el otro lado.','Capturas listas. Completá los datos y la autorización.'][photos.length];}
$('take-photo').addEventListener('click',()=>{try{photos.push(capture($('enroll-video')));renderPhotos();}catch(e){$('enroll-error').textContent=e.message;}});$('reset-photos').addEventListener('click',()=>{photos=[];renderPhotos();});
$('enroll-form').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target);$('save-resident').disabled=true;$('enroll-error').textContent='Procesando capturas localmente…';try{await post('/api/residents',{name:f.get('name'),unit:f.get('unit'),building:f.get('building'),consent:f.get('consent')==='on',adult_volunteer:f.get('adult')==='on',images:photos});closeEnrollment();await refresh();toast('Residente registrado. La verificación de acceso requiere superar reconocimiento y PAD.');}catch(err){$('enroll-error').textContent=err.message;$('save-resident').disabled=photos.length<3;}});
async function prepareLogin(){const r=await api('/api/auth/status');setupRequired=r.setup_required;$('setup-fields').hidden=!setupRequired;$('setup-confirm-wrap').hidden=!setupRequired;$('admin-token').required=setupRequired;$('setup-name').required=setupRequired;$('setup-confirm').required=setupRequired;$('login-title').textContent=setupRequired?'Crear primer administrador.':'Ingresá con tu cuenta.';$('login-description').textContent=setupRequired?'Usá la clave del cuadro de configuración inicial y elegí tu usuario y contraseña.':'Las operaciones de gestión se atribuyen a tu cuenta. La clave anterior ya no sirve para iniciar sesión.';$('login-submit').textContent=setupRequired?'Crear administrador':'Ingresar';}
$('login-form').addEventListener('submit',async e=>{e.preventDefault();$('login-submit').disabled=true;$('login-error').textContent='';try{const password=$('login-password').value;if(setupRequired&&password!==$('setup-confirm').value)throw new Error('Las contraseñas no coinciden.');const body={username:$('login-username').value,password,...(setupRequired?{setup_key:$('admin-token').value.trim(),name:$('setup-name').value}:{} )};const result=await post(setupRequired?'/api/auth/setup':'/api/auth/login',body);token=result.token;currentUser=result.user;lastInteraction=Date.now();sessionStorage.setItem('access-token',token);for(const id of ['login-password','setup-confirm','admin-token'])$(id).value='';$('login-dialog').close();setupRequired=false;await refresh();}catch(err){$('login-error').textContent=err.message;}finally{$('login-submit').disabled=false;}});
$('login-dialog').addEventListener('cancel',e=>e.preventDefault());
function clearSession(){stopCamera(false,false);stopObservations();if($('enroll-dialog').open)closeEnrollment();if($('password-dialog').open)$('password-dialog').close();if($('account-dialog').open)$('account-dialog').close();if($('release-dialog').open)$('release-dialog').close();$('account-password').value='';$('password-form').reset();token='';currentUser=null;sessionStorage.removeItem('access-token');residents=[];events=[];cameras=[];restrictionRows=[];auditRows=[];managedAccount=null;releaseId=null;restrictionNext=null;clearVisits();$('camera-form').reset();$('enroll-form').reset();$('release-form').reset();$('visit-cancel-reason').value='';$('resident-search').value='';for(const id of ['residents-body','events-body','recent-events','cameras-list','evaluation-results','pad-evaluation-results','trial-expected','restriction-list','users-list','audit-body','observation-grid'])$(id).replaceChildren();$('trial-result').textContent='';$('pad-trial-result').textContent='';$('pad-trial-form').reset();$('restriction-form').reset();$('user-form').reset();$('operator-summary').textContent='Sin sesión';$('audit-integrity').textContent='';for(const id of ['resident-count','event-count'])$(id).textContent='—';$('model-status').textContent='Sin sesión';applyRole();setView('access');}
$('logout').addEventListener('click',async()=>{try{await stopCamera(true,false);await post('/api/auth/logout');}catch(_){}finally{clearSession();await prepareLogin();$('login-dialog').showModal();}});
$('change-own-password').addEventListener('click',()=>{if(!currentUser)return;$('password-error').textContent='';$('password-form').reset();$('password-dialog').showModal();});
$('close-password').addEventListener('click',()=>{if(currentUser?.force_change){toast('Debés cambiar la contraseña o cerrar sesión.');return;}$('password-dialog').close();});
$('password-dialog').addEventListener('cancel',e=>{if(currentUser?.force_change)e.preventDefault();});
$('password-form').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target);try{if(f.get('next')!==f.get('confirm'))throw new Error('Las contraseñas no coinciden.');await post('/api/auth/password',{current_password:f.get('current'),password:f.get('next')});e.target.reset();clearSession();await prepareLogin();$('login-dialog').showModal();toast('Contraseña actualizada. Volvé a ingresar.');}catch(err){$('password-error').textContent=err.message;}});
window.addEventListener('pagehide',()=>{stopClip(false);if(stream)stream.getTracks().forEach(t=>t.stop());});

function renderTrialParticipants(){const select=$('trial-expected'),previous=select.value;select.replaceChildren(new Option('Persona no inscrita',''));for(const r of residents)select.add(new Option(r.name+' · '+r.unit,r.id));select.value=residents.some(r=>r.id===previous)?previous:'';}
function fraction(m){return m.total?m.count+' / '+m.total+' ('+(m.rate*100).toFixed(1)+' %)':'Sin datos';}
async function refreshEvaluation(){const report=await api('/api/evaluation/report');const target=$('evaluation-results');target.replaceChildren();$('evaluation-empty').hidden=report.total_trials>0;for(const s of report.sessions){const group=node('div',undefined,'evaluation-group');group.append(node('h3',s.session+' · '+s.phase),node('p',s.trials+' ensayos · '+s.participants+' códigos de participante · Padrón: '+s.configuration.gallery_size));const list=node('ul');for(const [label,key] of [['Inscritos identificados correctamente','known_correct'],['Inscritos rechazados','known_rejected'],['Identidad equivocada','known_wrong_identity'],['No inscritos aceptados por error','unknown_accepted'],['Capturas no aptas','capture_not_suitable']])list.append(node('li',label+': '+fraction(s.model[key])));group.append(list,node('p','Línea base, no inscritos aceptados: '+fraction(s.baseline_nearest_without_rejection.unknown_accepted)),node('p','Procesamiento mediana / p95: '+s.latency_processing_ms_median.toFixed(1)+' / '+s.latency_processing_ms_p95.toFixed(1)+' ms'));target.append(group);}return report;}
$('trial-form').addEventListener('submit',async e=>{e.preventDefault();const button=$('take-trial');button.disabled=true;try{if(!running||cameraId!=='browser-access'||!stream)throw new Error('Iniciá la cámara de esta computadora en Control de acceso.');const f=new FormData(e.target);const r=await post('/api/evaluation/trials',{image:capture($('video')),subject_code:f.get('subject_code'),session:f.get('session'),phase:f.get('phase'),condition:f.get('condition'),expected_id:f.get('expected_id')||null,consent:f.get('consent')==='on',independent_capture:f.get('independent')==='on'});const correct=r.expected_id===r.predicted_id;$('trial-result').textContent='Ensayo guardado: '+(correct?'resultado compatible con la etiqueta.':'difiere de la etiqueta: revisar el informe.')+' Motivo: '+r.reason;await refreshEvaluation();}catch(err){$('trial-result').textContent=err.message;}finally{button.disabled=false;}});
$('export-evaluation').addEventListener('click',async()=>{try{const report=await refreshEvaluation();if(!report.total_trials)throw new Error('Todavía no hay ensayos para exportar.');const url=URL.createObjectURL(new Blob([JSON.stringify(report,null,2)],{type:'application/json'}));const a=node('a');a.href=url;a.download='evaluacion_acceso_'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){toast(e.message);}});
