// Visitas: la autorización no acredita por sí sola identidad ni cruce.
let visitRows = [], visitNext = null, selectedVisit = null, visitRequestId = null;
function localDateInput(date) {
 const shifted = new Date(date.getTime() - date.getTimezoneOffset()*60000);
 return shifted.toISOString().slice(0,16);
}
function visitDefaults() {
 if (!$('visit-from').value) $('visit-from').value = localDateInput(new Date());
 if (!$('visit-until').value) $('visit-until').value = localDateInput(new Date(Date.now()+2*3600000));
}
function updateVisitDestination(){const common=$('visit-host').value==='administracion';$('visit-common-destination').hidden=!common;$('visit-common-building').required=common;$('visit-common-sector').required=common;}
$('visit-host').addEventListener('change',updateVisitDestination);
function renderVisitSelectors() {
 const host=$('visit-host'), chosen=host.value;
 host.replaceChildren(new Option('Seleccionar residente o administración',''),new Option('Administración / áreas comunes','administracion'));
 for(const r of residents) host.add(new Option(r.name+' · '+r.building+' · '+r.unit,r.id));
 host.value=chosen==='administracion'||residents.some(r=>r.id===chosen)?chosen:'';updateVisitDestination();
 const source=$('visit-camera-select'), old=source.value;
 source.replaceChildren(new Option('Cámara de esta computadora','browser-access'));
 for(const c of cameras.filter(c=>c.role==='access')) source.add(new Option(c.label,c.id));
 source.value=[...source.options].some(o=>o.value===old)?old:'browser-access';
 visitDefaults();
}
const visitLabels={autorizada:'Autorizada',programada:'Programada',vencida:'Vencida',dentro:'Sin salida registrada',finalizada:'Finalizada',cancelada:'Cancelada'};
function renderVisits() {
 const body=$('visits-body');body.replaceChildren();
 for(const v of visitRows) {
  const row=node('tr'), person=node('td'), host=node('td'), validity=node('td'), state=node('td'), action=node('td');
  person.append(node('strong',v.name),node('small',v.kind+(v.company?' · '+v.company:'')));
  host.append(node('span',v.host.building+' · Unidad '+v.host.unit),node('small',v.host.name));
  validity.append(node('span',fmt(v.valid_from)),node('small','Hasta '+fmt(v.valid_until)));
  const attention=v.display_status==='vencida'||v.authorization_expired_while_inside||v.revoked_at;
  state.append(node('span',visitLabels[v.display_status],attention?'visit-state attention':'visit-state'));
  if(v.status==='dentro'&&v.revoked_at)state.append(node('small','Autorización cancelada'));
  if(v.authorization_expired_while_inside)state.append(node('small','Fuera del horario autorizado'));
  const button=node('button','Ver / registrar','secondary');
  button.addEventListener('click',()=>openVisit(v.id).catch(e=>toast(e.message)));
  action.append(button);row.append(person,host,validity,state,action);body.append(row);
 }
 $('visits-empty').hidden=visitRows.length>0;
 $('visits-empty').textContent=$('visit-search').value?'No hay coincidencias con esta búsqueda.':'Todavía no hay autorizaciones para este filtro.';
 $('more-visits').hidden=visitNext===null;
}
let visitLoadVersion=0;
async function loadVisits(append=false) {
 const epoch=++visitLoadVersion;
 const params=new URLSearchParams({q:$('visit-search').value,inside:$('visits-only-inside').checked?'true':'false'});
 if(append&&visitNext!==null)params.set('before',visitNext);
 const data=await api('/api/visits?'+params);
 if(epoch!==visitLoadVersion)return;
 visitRows=append?visitRows.concat(data.items):data.items;visitNext=data.next_before;renderVisits();
}
async function openVisit(id) {
 const v=await api('/api/visits/'+id);selectedVisit=v;
 $('visit-detail-title').textContent=v.name;
 const info=$('visit-detail-summary');info.replaceChildren();
 for(const line of ['Tipo: '+v.kind+(v.company?' · '+v.company:''),'Destino: '+v.host.building+' · Unidad '+v.host.unit+' · '+v.host.name,'Motivo: '+v.purpose,'Autorizó: '+v.authorized_by,'Vigencia: '+fmt(v.valid_from)+' a '+fmt(v.valid_until),'Estado: '+visitLabels[v.display_status]])info.append(node('p',line));
 if(v.revoked_at)info.append(node('p','Autorización cancelada el '+fmt(v.revoked_at)+'. Si hay entrada sin salida, todavía podés registrar su egreso.'));
 if(v.authorization_expired_while_inside)info.append(node('p','El horario autorizado terminó y todavía no se registró salida. Revisá la situación con seguridad.'));
 $('visit-reference').textContent='Referencia: '+v.reference_code;
 $('visit-identity-checked').checked=false;$('visit-crossing-observed').checked=false;$('visit-restrictions-checked').checked=false;
 $('visit-cancel-reason').value='';$('visit-action-result').textContent='';
 $('visit-cancel-controls').hidden=currentUser?.role!=='admin'||v.status==='finalizada'||v.status==='cancelada'||!!v.revoked_at;
 $('visit-movement-controls').hidden=!['autorizada','dentro'].includes(v.status);
 const history=$('visit-history');history.replaceChildren();
 for(const e of v.history)history.append(node('p',fmt(e.occurred_at)+' · '+e.action+(e.camera_label?' · '+e.camera_label:'')+(e.reason?' · '+e.reason:'')+(e.operator_name?' · Operador: '+e.operator_name:'')));
 visitMovementButtons();if(!$('visit-dialog').open)$('visit-dialog').showModal();
}
function visitMovementButtons() {
 const checked=$('visit-identity-checked').checked&&$('visit-crossing-observed').checked;
 $('visit-entry').disabled=!checked||!$('visit-restrictions-checked').checked||selectedVisit?.display_status!=='autorizada'||!!selectedVisit?.revoked_at;
 $('visit-exit').disabled=!checked||selectedVisit?.status!=='dentro';
}
$('visit-identity-checked').addEventListener('change',visitMovementButtons);
$('visit-crossing-observed').addEventListener('change',visitMovementButtons);$('visit-restrictions-checked').addEventListener('change',visitMovementButtons);
$('close-visit').addEventListener('click',()=>{$('visit-dialog').close();selectedVisit=null;});
$('visit-dialog').addEventListener('cancel',()=>{selectedVisit=null;});
async function visitMovement(direction) {
 if(!selectedVisit)return;const id=selectedVisit.id;
 $('visit-entry').disabled=true;$('visit-exit').disabled=true;
 try {
  await post('/api/visits/'+id+'/'+direction,{camera_id:$('visit-camera-select').value,identity_checked:$('visit-identity-checked').checked,crossing_observed:$('visit-crossing-observed').checked,restrictions_checked:$('visit-restrictions-checked').checked});
  await refresh();await openVisit(id);toast(direction==='entry'?'Entrada de visita confirmada.':'Salida de visita confirmada.');
 }catch(e){try{await openVisit(id);}catch(_){}$('visit-action-result').textContent=e.message;visitMovementButtons();}
}
$('visit-entry').addEventListener('click',()=>visitMovement('entry'));
$('visit-exit').addEventListener('click',()=>visitMovement('exit'));
$('visit-cancel').addEventListener('click',async()=>{
 if(!selectedVisit)return;const id=selectedVisit.id,reason=$('visit-cancel-reason').value.trim();
 if(reason.length<3){$('visit-action-result').textContent='Indicá un motivo de al menos tres caracteres.';return;}
 if(!confirm('¿Cancelar esta autorización? Si tiene una entrada sin salida, el sistema conservará ese estado hasta registrar el egreso.'))return;
 $('visit-cancel').disabled=true;
 try{await post('/api/visits/'+id+'/cancel',{reason});await refresh();await openVisit(id);toast('Autorización cancelada.');}
 catch(e){$('visit-action-result').textContent=e.message;}finally{$('visit-cancel').disabled=false;}
});
$('visit-form').addEventListener('input',()=>{visitRequestId=null;});
$('visit-form').addEventListener('submit',async e=>{
 e.preventDefault();const form=e.target,f=new FormData(form),button=$('create-visit');button.disabled=true;$('visit-form-result').textContent='';
 try{
  visitRequestId=visitRequestId||crypto.randomUUID();
  const data={request_id:visitRequestId,name:f.get('name'),kind:f.get('kind'),company:f.get('company'),purpose:f.get('purpose'),host_id:f.get('host_id')==='administracion'?null:f.get('host_id'),host_kind:f.get('host_id')==='administracion'?'administracion':'residente',building:f.get('building')||'',destination:f.get('destination')||'Áreas comunes',authorized_by:f.get('authorized_by'),valid_from:new Date(f.get('valid_from')).toISOString(),valid_until:new Date(f.get('valid_until')).toISOString(),authorization_confirmed:f.get('authorization_confirmed')==='on',privacy_notice_given:f.get('privacy_notice_given')==='on',external_record_id:f.get('external_record_id')||null,external_identity_verified:f.get('external_identity_verified')==='on'};
  const result=await post('/api/visits',data);visitRequestId=null;form.reset();visitDefaults();await refresh();await openVisit(result.id);toast('Autorización creada. El código es una referencia, no una apertura de puerta.');
 }catch(err){$('visit-form-result').textContent=err.message;}finally{button.disabled=false;}
});
$('refresh-visits').addEventListener('click',()=>refresh().catch(e=>toast(e.message)));
$('search-visits').addEventListener('click',()=>loadVisits().catch(e=>toast(e.message)));
$('visit-search').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();loadVisits().catch(err=>toast(err.message));}});
$('visits-only-inside').addEventListener('change',()=>loadVisits().catch(e=>toast(e.message)));
$('more-visits').addEventListener('click',()=>loadVisits(true).catch(e=>toast(e.message)));
function clearVisits() {
 visitLoadVersion++;visitRows=[];visitNext=null;selectedVisit=null;visitRequestId=null;
 if($('visit-dialog').open)$('visit-dialog').close();
 for(const id of ['visits-body','visit-detail-summary','visit-history'])$(id).replaceChildren();
 $('visit-reference').textContent='';$('visit-host').replaceChildren();$('visit-form').reset();
 $('visit-form-result').textContent='';$('visit-action-result').textContent='';
 $('visits-authorized').textContent='—';$('visits-inside').textContent='—';
}


let restrictionRows=[], restrictionNext=null, releaseId=null, managedAccount=null, auditRows=[];
function renderRestrictionResident(){const select=$('restriction-resident'),chosen=select.value;select.replaceChildren(new Option('Registro externo manual',''));for(const r of residents)select.add(new Option(r.name+' · '+r.building+' · '+r.unit,r.id));select.value=residents.some(r=>r.id===chosen)?chosen:'';if(!$('restriction-from').value)$('restriction-from').value=localDateInput(new Date());if(!$('restriction-until').value)$('restriction-until').value=localDateInput(new Date(Date.now()+86400000));}
async function loadRestrictions(append=false){const params=new URLSearchParams({q:$('restriction-search').value});if(append&&restrictionNext)params.set('before',restrictionNext);const r=await api('/api/restrictions?'+params);restrictionRows=append?restrictionRows.concat(r.items):r.items;restrictionNext=r.next_before;const list=$('restriction-list');list.replaceChildren();if(!restrictionRows.length)list.append(node('p','No hay coincidencias en los registros internos.','section-note'));for(const item of restrictionRows){const row=node('div',undefined,'camera-item'),info=node('div',undefined,'camera-item-detail');info.append(node('strong',item.name),node('small',item.reference+' · '+item.state+' · Hasta '+fmt(item.valid_until)));if(item.reason)info.append(node('small','Motivo: '+item.reason));row.append(info);if(currentUser?.role==='admin'&&!item.released_at){const b=node('button','Levantar','secondary');b.addEventListener('click',()=>{releaseId=item.id;$('release-form').reset();$('release-error').textContent='';$('release-dialog').showModal();});row.append(b);}list.append(row);}$('more-restrictions').hidden=!restrictionNext;const select=$('visit-external-record'),chosen=select.value;select.replaceChildren(new Option('Sin asociación: revisar manualmente',''));for(const r of restrictionRows.filter(r=>r.type==='externo_manual'))select.add(new Option(r.name+' · '+r.reference+' · '+r.state,r.id));select.value=[...select.options].some(o=>o.value===chosen)?chosen:'';}
$('search-restrictions').addEventListener('click',()=>loadRestrictions().catch(e=>toast(e.message)));$('restriction-search').addEventListener('keydown',e=>{if(e.key==='Enter')loadRestrictions().catch(err=>toast(err.message));});$('more-restrictions').addEventListener('click',()=>loadRestrictions(true).catch(e=>toast(e.message)));
$('restriction-form').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target);try{await post('/api/restrictions',{resident_id:f.get('resident_id')||null,name:f.get('name'),reference:f.get('reference'),reason:f.get('reason'),valid_from:new Date(f.get('valid_from')).toISOString(),valid_until:new Date(f.get('valid_until')).toISOString(),identity_verified:f.get('identity_verified')==='on',authorized_decision:f.get('authorized_decision')==='on'});e.target.reset();renderRestrictionResident();await loadRestrictions();$('restriction-error').textContent='';toast('Restricción guardada con vencimiento. Las salidas siguen permitidas.');}catch(err){$('restriction-error').textContent=err.message;}});
$('close-release').addEventListener('click',()=>$('release-dialog').close());$('release-form').addEventListener('submit',async e=>{e.preventDefault();try{await post('/api/restrictions/'+releaseId+'/release',{reason:new FormData(e.target).get('reason')});$('release-dialog').close();await loadRestrictions();toast('Restricción levantada.');}catch(err){$('release-error').textContent=err.message;}});
async function loadUsers(){const rows=await api('/api/users');const list=$('users-list');list.replaceChildren();for(const user of rows){const row=node('div',undefined,'camera-item'),info=node('div',undefined,'camera-item-detail');info.append(node('strong',user.name),node('small',user.username+' · '+user.role+' · '+(user.active?'Activa':'Desactivada')+(user.force_change?' · Debe cambiar contraseña':'')));row.append(info);if(user.id!==currentUser.id){const button=node('button','Administrar','secondary');button.addEventListener('click',()=>{managedAccount=user;$('account-title').textContent=user.username;$('account-role').value=user.role;$('account-active').checked=user.active;$('account-password').value='';$('account-error').textContent='';$('account-dialog').showModal();});row.append(button);}list.append(row);}}
