$('user-form').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target);try{await post('/api/users',{username:f.get('username'),name:f.get('name'),password:f.get('password'),role:f.get('role')});e.target.reset();await loadUsers();toast('Cuenta creada. Deberá cambiar la contraseña al ingresar.');}catch(err){$('user-error').textContent=err.message;}});
$('close-account').addEventListener('click',()=>{$('account-password').value='';$('account-dialog').close();});
$('save-account').addEventListener('click',async()=>{try{await api('/api/users/'+managedAccount.id,{method:'PATCH',body:JSON.stringify({role:$('account-role').value,active:$('account-active').checked})});$('account-dialog').close();await loadUsers();toast('Cuenta actualizada; sesiones revocadas.');}catch(e){$('account-error').textContent=e.message;}});
