async function loadAudit(append=false){const extra=append&&auditRows.length?'?before='+auditRows.at(-1).id:'';const r=await api('/api/audit'+extra);$('audit-reconcile-form').hidden=!r.incident;if(r.incident)$('audit-reconcile-error').textContent='Pendiente: '+r.incident.method+' '+r.incident.resource;auditRows=append?auditRows.concat(r.items):r.items;$('audit-integrity').textContent=r.integrity.valid?'Integridad local verificada · '+r.integrity.checked+' registros conservados.':'ATENCIÓN: '+r.integrity.error;const body=$('audit-body');body.replaceChildren();for(const entry of auditRows){const tr=node('tr');for(const value of [fmt(entry.occurred_at),entry.operator?.name||entry.operator?.username||'—',entry.action,entry.resource_path||'Operación local'])tr.append(node('td',value));body.append(tr);}$('more-audit').hidden=r.items.length<100;}
$('refresh-audit').addEventListener('click',()=>loadAudit().catch(e=>toast(e.message)));$('more-audit').addEventListener('click',()=>loadAudit(true).catch(e=>toast(e.message)));
let observationRunning=new Set(),observationEpoch=0;
function renderObservations(){const grid=$('observation-grid');const old=new Map([...grid.children].map(n=>[n.dataset.id,n]));grid.replaceChildren();for(const c of cameras.filter(c=>c.role==='observe')){let card=old.get(c.id);if(!card){card=node('div',undefined,'observation-card');card.dataset.id=c.id;const picture=node('img');picture.alt='Última captura de '+c.label;picture.hidden=true;const text=node('p','Vista detenida','fineprint'),start=node('button','Ver','secondary'),stop=node('button','Detener','secondary');start.addEventListener('click',async()=>{try{await post('/api/cameras/'+c.id+'/connect');observationRunning.add(c.id);picture.hidden=false;text.textContent='Conectando…';if(observationRunning.size===1)observationLoop(++observationEpoch);}catch(e){text.textContent=e.message;}});stop.addEventListener('click',async()=>{observationRunning.delete(c.id);picture.removeAttribute('src');picture.hidden=true;text.textContent='Vista detenida';try{await post('/api/cameras/'+c.id+'/disconnect');}catch(e){text.textContent=e.message;}});card.append(node('strong',c.label),picture,text,start,stop);}grid.append(card);}for(const id of observationRunning)if(!cameras.some(c=>c.id===id))observationRunning.delete(id);}
async function observationLoop(epoch){let index=0;while(epoch===observationEpoch&&observationRunning.size&&token){const ids=[...observationRunning],id=ids[index++%ids.length];const card=[...$('observation-grid').children].find(n=>n.dataset.id===id);try{const result=await post('/api/cameras/'+id+'/analyze?mode=detect');if(epoch!==observationEpoch)return;if(card&&observationRunning.has(id)){const img=card.querySelector('img');if(result.image)img.src=result.image;card.querySelector('p').textContent=(result.face_count??result.boxes.length)+' rostros · Sin identificación';}}catch(e){if(card)card.querySelector('p').textContent=e.message;}await new Promise(resolve=>setTimeout(resolve,2000));}}
function stopObservations(){observationEpoch++;observationRunning.clear();for(const img of $('observation-grid').querySelectorAll('img'))img.removeAttribute('src');}
async function boot(){applyRole();try{await prepareLogin();if(token&&!setupRequired){await refresh();}else{token='';sessionStorage.removeItem('access-token');$('login-dialog').showModal();}}catch(e){$('login-error').textContent=e.message;if(!$('login-dialog').open)$('login-dialog').showModal();}}

$('export-report-html').addEventListener('click',async()=>{try{const report=await refreshEvaluation();if(!report.total_trials)throw new Error('Primero necesitás ensayos reales para generar el informe.');const sessionAtSend=token;const res=await fetch('/api/evaluation/report.html',{headers:{Authorization:'Bearer '+token}});if(!res.ok)throw new Error('No se pudo generar el informe.');const blob=await res.blob();if(sessionAtSend!==token)return;const url=URL.createObjectURL(blob),link=node('a');link.href=url;link.download='informe_acceso_'+new Date().toISOString().slice(0,10)+'.html';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){toast(e.message);}});

let clipState=null;
function stopClip(save=true){if(clipState){clipState.save=save;if(clipState.recorder.state!=='inactive')clipState.recorder.stop();}}
$('start-clip').addEventListener('click',()=>{try{if(!currentUser||!running||!stream||cameraId!=='browser-access')throw new Error('Iniciá la cámara de este equipo. Los flujos IP requieren su DVR o una integración de grabación específica.');if(!window.MediaRecorder)throw new Error('Este entorno no admite grabación WebM.');if(clipState)return;if(!confirm('¿Grabar un clip local de hasta 2 minutos, sin audio? Confirmá autorización y finalidad informada para las personas participantes. El archivo descargado queda bajo tu responsabilidad y no se borra con la retención de la base.'))return;const mime=MediaRecorder.isTypeSupported('video/webm;codecs=vp8')?'video/webm;codecs=vp8':'video/webm';const recorder=new MediaRecorder(stream,{mimeType:mime,videoBitsPerSecond:1500000});const state={recorder,chunks:[],save:true,token};clipState=state;recorder.ondataavailable=e=>{if(e.data.size)state.chunks.push(e.data);};recorder.onstop=()=>{clearTimeout(state.timer);if(state.save&&state.token===token&&state.chunks.length){const url=URL.createObjectURL(new Blob(state.chunks,{type:'video/webm'})),a=node('a');a.href=url;a.download='clip_acceso_'+new Date().toISOString().replace(/[:.]/g,'-')+'.webm';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}state.chunks=[];if(clipState===state)clipState=null;$('start-clip').disabled=false;$('stop-clip').disabled=true;$('clip-status').textContent='Clip finalizado · exportaciones bajo tu custodia';};recorder.onerror=()=>{state.save=false;toast('No se pudo completar el clip.');stopClip(false);};recorder.start(1000);state.timer=setTimeout(()=>stopClip(true),120000);$('start-clip').disabled=true;$('stop-clip').disabled=false;$('clip-status').textContent='GRABANDO · sin audio · se detendrá a los 2 minutos';}catch(e){toast(e.message);}});
$('stop-clip').addEventListener('click',()=>stopClip(true));

$('audit-reconcile-form').addEventListener('submit',async e=>{e.preventDefault();try{await post('/api/audit/reconcile',{reason:new FormData(e.target).get('reason')});e.target.reset();$('audit-reconcile-error').textContent='';await loadAudit();toast('Revisión documentada. No se reconstruyó la evidencia que faltaba.');}catch(err){$('audit-reconcile-error').textContent=err.message;}});

boot();

for(const event of ['pointerdown','keydown','touchstart'])document.addEventListener(event,()=>{lastInteraction=Date.now();},{passive:true});
setInterval(()=>{if(token&&Date.now()-lastInteraction>15*60000){const oldToken=token;clearSession();fetch('/api/auth/logout',{method:'POST',headers:{Authorization:'Bearer '+oldToken,'Content-Type':'application/json'},body:'{}'}).catch(()=>{});prepareLogin().then(()=>{if(!$('login-dialog').open)$('login-dialog').showModal();}).catch(()=>{});}},10000);

function renderPad(pad){const el=$('pad-status');el.classList.remove('pad-good','pad-warning','pad-danger');$('pad-status-text').textContent=pad?.passed?'PAD superado · piloto':pad?.state==='posible_presentacion'?'Posible foto o pantalla':pad?.state==='pendiente'?'Comprobando PAD · '+pad.samples+'/'+pad.required:'Verificación PAD pendiente';$('pad-status-detail').textContent=pad?.message||'Se necesitan capturas recientes; sin PAD no se habilita el registro facial.';el.classList.add(pad?.passed?'pad-good':pad?.state==='posible_presentacion'?'pad-danger':'pad-warning');}
async function refreshPadEvaluation(){const report=await api('/api/evaluation/pad/report');const target=$('pad-evaluation-results');target.replaceChildren();$('pad-evaluation-empty').hidden=report.total_trials>0;for(const session of report.sessions){const group=node('div',undefined,'evaluation-group');group.append(node('h3',session.session+' · '+session.phase),node('p',session.trials+' capturas · '+session.participants+' códigos'),node('p','Presentaciones aceptadas por el clasificador: '+fraction(session.attack_accepted_operational)),node('p','Personas reales rechazadas: '+fraction(session.real_rejected_operational)),node('p','Capturas no aptas: '+session.unsuitable_captures));target.append(group);}return report;}
$('pad-trial-form').addEventListener('submit',async e=>{e.preventDefault();try{if(!running)throw new Error('Iniciá la cámara de acceso seleccionada.');const f=new FormData(e.target);const row=await post('/api/evaluation/pad/trials',{image:cameraId==='browser-access'?capture($('video')):null,camera_id:cameraId,subject_code:f.get('subject_code'),session:f.get('session'),phase:f.get('phase'),presentation:f.get('presentation'),condition:f.get('condition'),consent:f.get('consent')==='on',independent_capture:f.get('independent_capture')==='on'});$('pad-trial-result').textContent='Captura guardada: '+(row.pad_capture_accepted?'clasificador acepta.':'clasificador rechaza o no puede evaluar.')+' No crea movimientos ni certifica el acceso.';await refreshPadEvaluation();}catch(err){$('pad-trial-result').textContent=err.message;}});
$('export-pad-report').addEventListener('click',async()=>{try{const report=await refreshPadEvaluation();if(!report.total_trials)throw new Error('Todavía no hay ensayos PAD para exportar.');const url=URL.createObjectURL(new Blob([JSON.stringify(report,null,2)],{type:'application/json'})),a=node('a');a.href=url;a.download='evaluacion_pad_'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){toast(e.message);}});
$('clear-pad-trials').addEventListener('click',async()=>{if(!confirm('¿Borrar los ensayos PAD de la base activa? Las exportaciones se gestionan aparte.'))return;try{await api('/api/evaluation/pad/trials',{method:'DELETE'});await refreshPadEvaluation();}catch(e){toast(e.message);}});
